var C = ARISTO.colors;
var scoreIn = document.getElementById('score');
var scoreV = document.getElementById('scoreV');
var readout = document.getElementById('readout');

var branches = [
  { kind: 'if',   label: 'if score >= 90:',       body: 'grade = "A"', test: function(s){ return s >= 90; }, grade: 'A' },
  { kind: 'elif', label: 'elif score >= 70:',      body: 'grade = "B"', test: function(s){ return s >= 70; }, grade: 'B' },
  { kind: 'elif', label: 'elif score >= 50:',      body: 'grade = "C"', test: function(s){ return s >= 50; }, grade: 'C' },
  { kind: 'else', label: 'else:',                  body: 'grade = "F"', test: function(){ return true; },   grade: 'F' }
];

function evaluate(s) {
  var results = [];
  var ran = -1;
  for (var i = 0; i < branches.length; i++) {
    var truth = branches[i].test(s);
    results.push(truth);
    if (ran === -1 && truth) ran = i;
  }
  return { results: results, ran: ran };
}

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var s = +scoreIn.value;
  var ev = evaluate(s);
  var n = branches.length;
  var padTop = 10, padBottom = 10, padSide = 10;
  var gap = 8;
  var boxH = (h - padTop - padBottom - gap * (n - 1)) / n;
  var boxW = w - padSide * 2;
  var x = padSide;

  ctx.font = '600 13px system-ui, sans-serif';
  ctx.textBaseline = 'middle';

  for (var i = 0; i < n; i++) {
    var y = padTop + i * (boxH + gap);
    var b = branches[i];
    var truth = ev.results[i];
    var isRun = (ev.ran === i);

    var fill = C.sunk;
    var stroke = C.line;
    var textColor = C.body;

    if (isRun) {
      fill = C.accentText;
      stroke = C.accentText;
      textColor = C.surface;
    } else if (truth && b.kind !== 'else') {
      fill = C.surface;
      stroke = C.success;
      textColor = C.ink;
    } else if (b.kind === 'else' && ev.ran !== i) {
      fill = C.sunk;
      stroke = C.line;
      textColor = C.muted;
    } else {
      fill = C.sunk;
      stroke = C.line;
      textColor = C.muted;
    }

    ctx.fillStyle = fill;
    ctx.strokeStyle = stroke;
    ctx.lineWidth = isRun ? 3 : 1.5;
    roundRect(ctx, x, y, boxW, boxH, 8);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = textColor;
    ctx.font = '600 13px ui-monospace, Menlo, Consolas, monospace';
    ctx.fillText(b.label, x + 10, y + boxH * 0.34);
    ctx.font = '13px ui-monospace, Menlo, Consolas, monospace';
    ctx.fillText('    ' + b.body, x + 10, y + boxH * 0.68);

    if (b.kind !== 'else') {
      ctx.font = '600 11px system-ui, sans-serif';
      var mark = truth ? '\u2713 true' : '\u2717 false';
      var markColor = isRun ? C.surface : (truth ? C.success : C.muted);
      ctx.fillStyle = markColor;
      var mw = ctx.measureText(mark).width;
      ctx.fillText(mark, x + boxW - mw - 10, y + boxH * 0.5);
    } else if (isRun) {
      ctx.font = '600 11px system-ui, sans-serif';
      ctx.fillStyle = C.surface;
      var mark2 = 'runs';
      var mw2 = ctx.measureText(mark2).width;
      ctx.fillText(mark2, x + boxW - mw2 - 10, y + boxH * 0.5);
    }
  }
}, 0.62);

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function update() {
  var s = +scoreIn.value;
  scoreV.textContent = String(s);
  var ev = evaluate(s);
  var grade = branches[ev.ran].grade;
  readout.textContent = 'Score = ' + s + ' \u2192 grade is ' + grade;
  plot.redraw();
}

scoreIn.addEventListener('input', update);
update();
